import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique {@link File} inside {@code dir} with the given {@code name}.
     * <p>
     * The method protects against directory‑traversal attacks by normalizing the
     * resolved path and ensuring it stays within {@code dir}. If the resolved
     * path escapes {@code dir}, an {@link IllegalArgumentException} is thrown.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the desired file name; may contain query parameters which are stripped
     * @return a {@link File} that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("Name must not be null");
        }

        // Strip query parameters (e.g., "file.txt?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested name against the base directory and normalize
        Path dirPath = dir.toPath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the target path is still within the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempted to create a file outside the allowed directory: " + name);
        }

        File file = targetPath.toFile();

        // Generate a unique filename if one already exists
        int dot = name.indexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
```

