import org.codehaus.plexus.util.IOUtil;
import org.codehaus.plexus.util.StringUtils;

public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    /**
     * Extracts a single entry from the archive into {@code dir}. The method now performs
     * strict validation of {@code entryName} to prevent Zip‑Slip attacks. It ensures that
     * the resolved extraction path is strictly within {@code dir} by comparing the
     * canonical paths. If the entry attempts to escape the target directory, an
     * {@link ArchiverException} is thrown.
     *
     * @param srcF              the source file (unused in this implementation)
     * @param dir               the target extraction directory
     * @param compressedInputStream the input stream containing the compressed data
     * @param entryName         the name of the entry inside the archive
     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the Unix permission mode (may be {@code null})
     * @param symlinkDestination the target of a symbolic link (may be {@code null})
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry is unsafe or cannot be extracted
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file relative to the extraction directory
        final File targetFile = FileUtils.resolveFile(dir, entryName);

        // Canonicalize both the extraction directory and the target file
        final Path canonicalDirPath = dir.getCanonicalFile().toPath();
        final Path canonicalTargetPath = targetFile.getCanonicalFile().toPath();

        // Verify that the target path is within the extraction directory
        if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException("Entry is outside of the target directory (" + entryName + ")");
        }

        // Prevent accidental overwrite of existing symbolic links when the entry is a regular file
        if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTargetPath)) {
            throw new ArchiverException("Attempt to overwrite existing symbolic link (" + entryName + ")");
        }

        try {
            // Skip extraction if the file already exists and is newer than the entry
            if (!isOverwrite() && targetFile.exists() && (targetFile.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Ensure parent directories exist
            final File parentDir = targetFile.getParentFile();
            if (parentDir != null) {
                parentDir.mkdirs();
            }

            // Handle symbolic links
            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(targetFile, new File(symlinkDestination));
            } else if (isDirectory) {
                // Create directory entry
                targetFile.mkdirs();
