public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // ... other methods ...

    /**
     * Validates a media type component (major or subtype). A component is considered valid if it
     * is either the single asterisk "*" (used for wildcards) or a token as defined by RFC 7230.
     *
     * <p>The RFC defines a token as one or more of the following characters:
     * {@code !#$%&'*+-.^_`|~} plus ASCII letters and digits.  No whitespace or control
     * characters are allowed.  This strict whitelist prevents header injection via
     * newline, carriage‑return, or other unsafe characters.</p>
