            return false;
        }

        // Wildcard is allowed only as a single '*'
        if ("*".equals(str)) {
            return true;
        }

        // Token regex according to RFC 7230 §3.2.6
        // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
        //        "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
        // token = 1*tchar
        // We also explicitly exclude control characters and whitespace.
        final Pattern TOKEN_PATTERN = Pattern.compile("[!#$%&'*+\\-.^_`|~0-9A-Za-z]+");
