        if (!referencedIds.contains(response.getID())) {
            LOG.fine("Signature does not reference the Response element");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        // All assertion IDs must be referenced
        for (org.opensaml.saml.saml2.core.Assertion assertion : response.getAssertions()) {
            String assertionId = assertion.getID();
            if (!referencedIds.contains(assertionId)) {
                LOG.fine("Signature does not reference assertion ID: " + assertionId);
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }
