    private boolean hasRequiredTransforms(Reference ref) {
        if (ref.getTransforms() == null) {
            return false;
        }
        boolean hasEnveloped = false;
        boolean hasExclusiveC14n = false;
        for (Transform t : ref.getTransforms()) {
            String algo = t.getAlgorithm();
            if (Transform.ENVELOPED.equals(algo)) {
                hasEnveloped = true;
            } else if (Transform.EXCLUSIVE_C14N.equals(algo)) {
                hasExclusiveC14n = true;
            }
        }
        return hasEnveloped && hasExclusiveC14n;
    }

