     * checks for premature end of stream, and ensures that the output buffer is
     * not overrun. Any malformed input results in an {@link IOException}.
     *
     * @param in  the source stream containing compressed data
     * @param out the destination buffer that will receive the decompressed bytes
     * @throws IOException if the stream ends unexpectedly or the data is malformed
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        if (in == null) {
            throw new IllegalArgumentException("Input stream cannot be null");
        }
        if (out == null) {
            throw new IllegalArgumentException("Output buffer cannot be null");
        }

        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading control byte");
            }

            if (n > 128) { // Run‑length encoded block
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading run value");
                }

                int runLength = n & 0x7F; // lower 7 bits give the repeat count
                if (runLength == 0) {
