     * @throws ClassNotFoundException   if the class of a serialized object cannot be found.
     * @throws InvalidObjectException   if the deserialized data is malformed or unsafe.
     */
    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        // Perform default deserialization first
        in.defaultReadObject();

        // Validate the temporary file reference (if present)
        if (dfosFile != null) {
            String fileName = dfosFile.getName();
            // Reject null bytes and disallow path traversal characters
            if (fileName.contains("\0") || fileName.contains("/") || fileName.contains("\\")
                    || !fileName.matches("[A-Za-z0-9._-]+")) {
                throw new InvalidObjectException(
                        "Invalid temporary file name detected during deserialization: " + fileName);
            }
            if (!dfosFile.isFile()) {
                throw new InvalidObjectException(
                        "Temporary file does not exist or is not a regular file: " + dfosFile);
            }
        }

        // Obtain the output stream where the file content will be written
        try (OutputStream output = getOutputStream()) {
            if (cachedContent != null) {
                // Write cached content directly
                output.write(cachedContent);
            } else if (dfosFile != null) {
                // Copy from the temporary file to the destination
                try (FileInputStream input = new FileInputStream(dfosFile)) {
                    IOUtils.copy(input, output);
                }
                // Delete the temporary file only after successful copy
                if (!dfosFile.delete()) {
                    // Log warning – deletion failed but we continue
                    System.err.println("Warning: Failed to delete temporary file: " + dfosFile);
                }
                dfosFile = null;
            } else {
                // No data source available – this is an unexpected state
                throw new InvalidObjectException("No cached content or temporary file available during deserialization.");
