    /* --------------------------------------------------------------------- */
    /* Safe component type whitelist                                         */
    /* --------------------------------------------------------------------- */

    /** Set of component types considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES = new HashSet<>(
            Arrays.asList(
                    // Primitive wrappers
                    Boolean.class, Byte.class, Short.class, Integer.class, Long.class,
                    Float.class, Double.class, Character.class,
                    // Common numeric types
                    java.math.BigDecimal.class, java.math.BigInteger.class,
                    // String
                    String.class,
                    // Date/time types
                    java.util.Date.class,
                    java.time.LocalDate.class,
                    java.time.LocalDateTime.class,
                    java.time.OffsetDateTime.class,
                    java.time.ZonedDateTime.class,
                    java.time.Instant.class,
                    java.time.LocalTime.class,
                    java.time.YearMonth.class,
                    java.time.Year.class,
                    java.time.MonthDay.class,
                    java.time.Period.class,
                    java.time.Duration.class
            )
    );

    /**
     * Checks whether a component type is allowed for deserialization.
     *
     * @param cls the component class to check
     * @return {@code true} if the class is in the whitelist or is a primitive
     *         type; {@code false} otherwise
     */
    private static boolean isAllowedComponentType(Class<?> cls) {
        if (cls == null) {
            return false;
        }
        if (cls.isPrimitive()) {
            return true;
        }
        if (SAFE_COMPONENT_TYPES.contains(cls)) {
            return true;
        }
        // Allow enums (they are inherently safe)
        return cls.isEnum();
