import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.Objects;

/**
 * Determines whether a self‑update request is allowed.
 *
 * <p>The original implementation only compared the contents of the request
 * against the stored user record.  It did not verify that the caller was
 * actually the owner of the account being updated, allowing an attacker to
 * change another user’s email address.  The patched version now ensures that
 * the authenticated user’s identifier matches the target user identifier
 * extracted from the request URL.  If the identifiers do not match, the
 * request is rejected.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods omitted for brevity

    /**
     * Checks whether the incoming request is allowed to perform a self‑update.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is authorized, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        /* --------------------------------------------------------------------
         * 1. Identify the authenticated user.
         * -------------------------------------------------------------------- */
        String authenticatedUserId = null;

        // Prefer the servlet container principal (e.g., Spring Security)
        if (request.getUserPrincipal() != null) {
            authenticatedUserId = request.getUserPrincipal().getName();
        } else {
            // Fallback: look for a session attribute that may hold the user id
            if (request.getSession(false) != null) {
                Object sessionAttr = request.getSession(false).getAttribute("userId");
                if (sessionAttr instanceof String) {
                    authenticatedUserId = (String) sessionAttr;
                }
            }
        }

        // If we cannot determine the authenticated user, reject the request
        if (authenticatedUserId == null) {
            return false;
        }

        /* --------------------------------------------------------------------
         * 2. Extract the target user id from the request URL.
         * -------------------------------------------------------------------- */
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Reject if the authenticated user does not own the target account
        if (!Objects.equals(authenticatedUserId, targetUserId)) {
            return false;
        }

        /* --------------------------------------------------------------------
         * 3. Load the existing user record from the database.
         * -------------------------------------------------------------------- */
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed
            // (the caller will create a new user).
            return true;
        }

        /* --------------------------------------------------------------------
         * 4. Parse the request body into a ScimUser instance.
         * -------------------------------------------------------------------- */
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        /* --------------------------------------------------------------------
         * 5. Perform field‑by‑field validation.
         * -------------------------------------------------------------------- */
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    // other methods omitted for brevity
}
